    for r in range(h):
        cs = [c for c in range(w) if grid[r][c] == mark]
        for a, b in zip(cs, cs[1:]):
            if b - a <= 1:
                continue
            # Require a marker at one endpoint to be part of a vertical run.
            supported = False
            for c in (a, b):
