        (v for row in grid for v in row),
        key=lambda v: sum(cell == v for row in grid for cell in row)
    )
    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] != background]
    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)

    out = [row[:] for row in grid]
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if r in (r0, r1) or c in (c0, c1):
                if out[r][c] == background:
                    out[r][c] = 2
    return out
